mutation InvoiceRequest($orderId: ID!) {
  invoiceRequest(orderId: $orderId) {
    errors {
      ...InvoiceError
    }
    invoice {
      ...Invoice
    }
    order {
      id
      invoices {
        ...Invoice
      }
    }
  }
}

fragment InvoiceError on InvoiceError {
  code
  field
  message
}

fragment Invoice on Invoice {
  id
  number
  createdAt
  url
  status
}
